insert into public.exercises(slug,name,status,family,movement_pattern,exercise_role,primary_muscles,secondary_muscles,required_equipment,skill_level,fatigue_cost,progression_suitability,rep_min,rep_max,education,caution_tags,content_version,license_key,review_status)
select e->>'slug',e->>'name','production',e->>'family',e->>'pattern',e->>'role',array(select jsonb_array_elements_text(e->'primaryMuscles')),array(select jsonb_array_elements_text(e->'secondaryMuscles')),array(select jsonb_array_elements_text(e->'requiredEquipment')),e->>'skill',(e->>'fatigueCost')::smallint,(e->>'progressionSuitability')::smallint,(e->'repRange'->>0)::smallint,(e->'repRange'->>1)::smallint,jsonb_build_object('setup',jsonb_build_array(e->'instructions'->>0),'execution',jsonb_build_array(e->'instructions'->>1,e->'instructions'->>2),'cues',e->'cues','mistakes',e->'mistakes'),array(select jsonb_array_elements_text(e->'cautionTags')),'1.0.0','STHENO_ORIGINAL','reviewed' from batch
